const $=s=>document.querySelector(s), page=$('#page'), modal=$('#modal');
const fresh=()=>({xp:0,coins:0,hero:'dog-1',matches:0,wins:0,answers:0,correct:0,subjects:{},missed:[],sound:true,music:true,musicVolume:.24,effectsVolume:.65,difficulty:'challenger',personalBests:{},battleTopics:['maths'],questionSeen:{},questionSerial:0});
let profile;try{profile={...fresh(),...JSON.parse(localStorage.getItem('quest-clash-v1')||'{}')}}catch{profile=fresh()}
let currentPage='home',game=null,quiz=null,keys={},last=0,raf=0,previousFocus=null;
let stick={pointerId:null,x:0,y:0},firePointerId=null;
initialiseQuestionHistory();ensureAvatar();petTab=ensureAvatar().species;unlockNoticeRank=highestUnlockedRank().rank;
function save(){ensureAvatar();try{localStorage.setItem('quest-clash-v1',JSON.stringify(profile))}catch{toast('Progress could not be saved in this browser.')}updateBar();const rank=highestUnlockedRank();if(rank.rank>unlockNoticeRank){GameAudio.effect('unlock');toast(rank.title+' unlocked! Visit Avatars to choose a new dog or cat.')}unlockNoticeRank=rank.rank}
function updateBar(){const h=ensureAvatar();const avatar=document.querySelector('.avatar');if(avatar){avatar.innerHTML=petPortrait(h);avatar.title=h.name+' · '+h.title}$('#coins').textContent=profile.coins;$('#level').textContent='LVL '+(Math.floor(profile.xp/150)+1);$('#level').title=profile.xp+' XP earned'}
function toast(t){document.querySelector('.toast')?.remove();let e=document.createElement('div');e.className='toast';e.setAttribute('role','status');e.textContent=t;document.body.append(e);setTimeout(()=>e.remove(),3500)}
function artwork(){return `<svg viewBox="0 0 600 360" aria-hidden="true"><defs><pattern id="grid" width="55" height="30" patternUnits="userSpaceOnUse" patternTransform="skewX(-28)"><path d="M55 0H0V30" fill="none" stroke="#a47dc0" stroke-opacity=".17"/></pattern><radialGradient id="glow"><stop stop-color="#caa3ff" stop-opacity=".45"/><stop offset="1" stop-color="#a672e6" stop-opacity="0"/></radialGradient></defs><circle cx="320" cy="160" r="210" fill="url(#glow)"/><path d="M36 235L315 80 573 235 300 376Z" fill="#352b4c"/><path d="M36 218L315 63 573 218 300 359Z" fill="#655579" stroke="#b49ac7" stroke-width="2"/><path d="M36 218L315 63 573 218 300 359Z" fill="url(#grid)"/><g fill="#886f9a" stroke="#3f3557" stroke-width="3"><path d="M118 175L173 144 218 170 163 202Z"/><path d="M118 175V205L163 231 218 200V170L163 202Z"/><path d="M382 215L436 186 478 209 424 240Z"/><path d="M382 215V244L424 269 478 239V209L424 240Z"/></g><g fill="#92a269" stroke="#49573a" stroke-width="3"><path d="M194 271L211 239 217 263 231 229 242 251 258 231 267 267 229 291Z"/><path d="M425 125L437 96 443 120 457 90 466 119 480 106 485 135 454 151Z"/></g><g fill="#92efdb" stroke="#3c8a92" stroke-width="3"><path d="M337 240L322 217 329 195 344 207 354 230Z"/><path d="M357 243L352 221 369 203 379 225Z"/></g><g transform="translate(370 150) rotate(12)"><ellipse cy="38" rx="30" ry="10" fill="#22182b55"/><rect x="-25" y="-14" width="50" height="49" rx="14" fill="#eea568" stroke="#4a3650" stroke-width="4"/><rect x="-19" y="-3" width="38" height="17" rx="5" fill="#48384f"/><path d="M-12 2L-6 6M12 2L6 6" stroke="#f4d767" stroke-width="4"/><path d="M0 -14V-28" stroke="#d7c3d9" stroke-width="5"/><circle cy="-29" r="6" fill="#f7bf66"/></g><g transform="translate(95 49) scale(.96)">${heroSVG(profile.hero).replace(/<svg[^>]*>|<\/svg>/g,'')}</g><g fill="#d9fa62"><path d="M312 27L318 41 333 46 319 52 313 67 307 53 292 47 307 41Z"/><path d="M506 170L510 179 520 183 510 187 506 197 502 187 493 183 502 179Z"/></g><g fill="#d6beed" font-size="25"><text x="244" y="100" transform="rotate(-12 244 100)">+</text><text x="495" y="84" transform="rotate(12 495 84)">♫</text><text x="331" y="302">✧</text></g></svg>`}
function navigate(p){document.body.classList.remove('in-battle');if(game){cancelAnimationFrame(raf);game=null}currentPage=p;document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('active',n.dataset.page===p));$('#crumb').textContent=({home:'PLAY',heroes:'AVATARS',progress:'MY PROGRESS',guide:'HOW TO PLAY',parents:'FOR GROWN-UPS'})[p]||'ARENA';const screens={home:home,heroes:heroes,progress:progress,guide:guide,parents:parents};page.innerHTML=screens[p]();window.scrollTo(0,0);updateBar()}
function heading(t,s,id=''){return `<div class="title-row"><div><h1>${t}</h1><p class="sub" ${id?'id="'+id+'"':''}>${s}</p></div><span class="status">SOLO ADVENTURE</span></div>`}
function home(){return `${heading('Ready for your next quest?','A little knowledge. A whole lot of power.')}${topicShortcuts()}<section class="hero"><div class="hero-copy"><div class="eyebrow"><i></i> YOUR BRAIN IS YOUR SUPERPOWER</div><h2>Small hero.<br><em>Massive potential.</em></h2><p>Outsmart the bots. Power up with knowledge.<br>Your next great adventure starts with a question.</p><button class="primary" data-action="mixed">Enter the arena <span style="margin-left:22px">➜</span></button><div class="small-caption">${selectedMode().name.toUpperCase()} · ${selectedMode().waves} WAVES · ${selectedMode().seconds}s PLAY TIME</div></div><div class="hero-art">${artwork()}</div><div class="hero-tag">THE KNOWLEDGE GROUNDS</div></section><div class="stat-strip"><div class="stat"><div class="stat-icon">✦</div><div><b>${profile.xp}</b><p>TOTAL XP EARNED</p></div></div><div class="stat"><div class="stat-icon">⚑</div><div><b>${profile.wins}</b><p>ARENA VICTORIES</p></div></div><div class="stat"><div class="stat-icon">◎</div><div><b>${profile.answers?Math.round(profile.correct/profile.answers*100):0}%</b><p>ANSWER ACCURACY</p></div></div></div>${difficultyCards()}${topicCatalogue()}<div class="bottom-callout"><div><h3>Less battling. More brain training.</h3><p>Try a 10-question quest with your choice of fields and timer.</p></div><button class="secondary" data-action="practice">Practice mode →</button></div>`}
function progress(){return `${heading('Look how far you’ve come.','Every question is a step forward. Keep exploring.')}<div class="stat-strip"><div class="stat"><div class="stat-icon">✦</div><div><b>${profile.xp}</b><p>XP EARNED</p></div></div><div class="stat"><div class="stat-icon">✓</div><div><b>${profile.correct} / ${profile.answers}</b><p>CORRECT ANSWERS</p></div></div><div class="stat"><div class="stat-icon">⚑</div><div><b>${profile.wins} / ${profile.matches}</b><p>WINS / FINISHED MATCHES</p></div></div></div><div class="info-panel"><h2>Your knowledge map</h2><p>Accuracy across all attempts. ${exploredQuestions()} of ${QUESTION_COUNT} questions explored on this device. Unseen questions come first; tricky-question review deliberately repeats items.</p>${SUBJECTS.map(s=>{let a=profile.subjects[s.id]||{correct:0,total:0};return `<div class="progress-row" style="--accent:${s.colour}"><b>${s.icon} ${s.name}</b><div class="track"><span style="width:${a.total?a.correct/a.total*100:0}%"></span></div><small>${a.correct}/${a.total}</small></div>`}).join('')}<button class="primary" data-action="review" ${profile.missed.length?'':'disabled'}>Practise tricky questions (${profile.missed.length})</button></div><div class="section-title"><h2>Adventure badges</h2></div><div class="badges">${[[profile.answers>=1,'✦','First spark','Answer your first question'],[profile.correct>=20,'🧠','Brain power','Get 20 answers correct'],[profile.wins>=1,'🏆','Arena ace','Win an arena match'],[LEARNING_FIELDS.every(f=>f.banks.some(id=>profile.subjects[id]?.total)),'🌏','All-rounder','Try all 13 learning fields']].map(b=>`<div class="badge ${b[0]?'':'locked'}"><span>${b[0]?'✓ ':''}${b[1]}</span><strong>${b[2]}</strong><p>${b[3]}</p></div>`).join('')}</div>`}
function guide(){return `${heading('Knowledge becomes life.','Prepare your loadout. Then face the arena.')}<div class="info-panel"><h2>01 · Pick your challenge and topics</h2><p>Choose Scout, Challenger or Expert on the home screen. Enter the arena to select one or more topics. Every warm-up has exactly 10 random questions total, mixed from your selected fields. Selecting 1, 8 or all 13 fields does not change the number of questions.</p><h2>02 · Earn your life bar</h2><p>Every correct answer gives 10 preparation points and one extra heart. Your starting battle life is your avatar’s base hearts plus your total correct answers. For example, a 4-heart avatar with 7 correct answers starts with 11 hearts. Incorrect answers still include explanations and earn learning XP.</p><h2>03 · Fight without question interruptions</h2><p>Once all 10 questions are complete, review your earned life and enter battle. Move with WASD, arrows or the joystick. Hold Space or Zap to attack a nearby visible bot. Press Shift or Dash to dodge, Q or Reload for extra energy, and E or Super for a nearby shockwave.</p><h2>04 · Keep moving</h2><p>Collect dropped energy crystals. Energy also slowly regenerates. Defeating six bots charges a super. Use cover, dodge aimed shots and leave warning circles. Challenger has 4 waves and a boss; Expert has 5 waves and a tougher boss. Scout has 3 waves to practise.</p><h2>05 · Learn, then improve your best</h2><p>Choose no question time limit or 60 seconds per question in round setup. Unanswered timed questions automatically advance and earn no heart. Combat has its own play timer and no quiz popups. Your match score and local personal best appear after battle. Practice mode has 10 questions and no combat. Choose fields and the question timer in round setup. Take breaks between adventures.</p></div>`}
function parents(){return `${heading('A little context for grown-ups.','An original learning game for curious minds, with Years 6–12 practice.')}<div class="info-panel"><p class="creator-credit">Created by Kat Choi in November 2026 for her son, Lukas Fok, whose love of learning and games inspired Quest Clash.</p><h2>What’s included</h2><p>${QUESTION_COUNT} questions and calculated variations across 13 learning fields: ${typeof LEARNING_FIELDS!=='undefined'?LEARNING_FIELDS.map(s=>s.name).join(', '):SUBJECTS.map(s=>s.name).join(', ')}. Topics are informed by Australian upper-primary learning areas. The bank contains 12,106 questions and calculated variations, including sourced pop-music knowledge. Many added entries are numerical or reading variations of a smaller set of skills; the total does not mean 12,000 different curriculum concepts. Levels 1–17 use Year 6 practice, levels 18–34 introduce Year 7 practice and levels 35–50 introduce Year 8 practice. Levels 51–64 introduce Year 9, levels 65–79 Year 10, levels 80–89 Year 11 and levels 90–100 Year 12 extension practice. The optional Senior Challenge has five questions at the chosen Year 10, 11 or 12 level; correct answers earn 50 points in Year 10, 80 in Year 11 and 100 in Year 12, with matching credits (maximum 250, 400 or 500 per round). Every game has 100 separate stages; only a successful clear unlocks the next stage. School sequences vary; year labels guide supplementary practice and are not a complete curriculum assessment. Numerical variants reuse skills with different values. Friends in a shared room receive the host’s question stage so everyone answers the same questions. The 13 learning fields combine related question banks: Science includes biology, chemistry, physics, Earth and space; Arts includes music; Sport includes health; Society includes civics, economics and current issues; Technology includes design.</p><p>This is a supplementary practice game, not a complete curriculum, accredited assessment or a substitute for teaching. State and school sequences vary. Five original environment soundtracks play after your first tap, following the selected battlefield. Music and sound effects have separate toggles and volume controls in Audio. Music quietens during questions and pauses in hidden tabs. Music learning includes a generated pitch example; reading comprehension uses short original passages. Logic and Puzzles contains IQ-style practice puzzles, not a standardised IQ test or an intelligence score. Current Issues covers age-appropriate scenarios about AI, media, climate, waste and inclusion, with source links. Sources were checked on 10 November 2026; this is not a live news feed. Question history is saved locally and included in optional cloud saves and favours unseen questions across sessions.</p><h2>Learning and rewards</h2><p>Every answer includes an explanation. Battle warm-ups contain exactly 10 questions in total, randomly mixed from the selected topics. A correct answer earns 10 preparation points and one extra battle heart. Starting life equals avatar base hearts plus correct answers; the bar’s full capacity shows base hearts plus all available warm-up questions. Questions do not interrupt combat. Correct answers earn 10 XP and 5 coins; other attempts earn 2 XP. Win XP bonuses depend on the selected challenge: Scout adds 30 XP, Challenger 60 XP and Expert 100 XP. Successful clears award one earned credit per score point. Personal-best scores are stored on this device by difficulty and avatar rank. Levels increase every 150 XP up to level 100. Mastery from level 27 adds health and damage, and enemies scale with the extra power. Six weapon styles unlock at levels 1, 5, 10, 20, 35 and 50. Fur, hair, eyes, outfits and accessories can be customised. Left- or right-handed control layouts and control positions are saved locally. Forty dog and cat avatars unlock as twenty rank pairs from player level 1 to 50. Each of the eight games has five matching courses with previews; cover grows from 6 to 12 blocks, and hazards intensify as players reach levels 10, 25 and 40. Higher avatars have stronger attacks and more health; monsters scale to the equipped rank. Avatar ranks are fictional game progression, not breed intelligence ratings. Eight original games are available: Quest Clash Arena, Turbo Tails Rally, Cloudstep Expedition, Crystal Keep, Meteor Meadow, Relic Run, Orbit Rangers and Echo Vault. Each has a ten-question warm-up. Live cooperative play is available in the arena. Armour, shields, outfits, accessories and a festive Christmas collection are unlocked with earned credits; there are no real-money purchases. Every correct answer within 30 seconds earns +5 XP and +3 credits; a perfect round earns +25 XP and +25 credits, and ten fast correct answers earn another +25 XP and +25 credits. Successful game clears award one credit per score point. No advertisements or chat. Friend score challenges are shared rounds played in turns. Live co-op rooms let 2–4 friends answer the same questions and battle together with visible avatars. The host simulates combat and must keep the tab open. Live play attempts a direct data connection between room members for faster updates, and uses the authenticated room server when a direct connection is unavailable. No camera or microphone permission is required. Live rooms are casual play, not a verified competitive leaderboard.</p><h2>Progress and privacy</h2><p>Progress is stored in this browser on this device. It can be lost if browser storage is cleared. An optional player ID and password allow cloud saves and cross-device restoration through Save / Log in. Passwords are salted and hashed, and cloud saves include the player’s learning history, avatar, credits and settings. Password recovery is not available; keep credentials with a parent. An optional player nickname is saved locally. A nickname is required for friend challenges and is included with the score in the shared challenge link. Use a nickname rather than a full name. No age or email is requested. Player accounts are optional. This game is publicly playable through its shared link; progress is local unless the player opts in to cloud saving. Live rooms send player nicknames, avatar choices, quiz scores and game movement to the room server and other room members. Anyone with a room code can join before a round starts; share it only with intended friends. Rooms expire after two hours and old room records are cleared when new rooms are created. No camera or microphone is used.</p><h2>Curriculum references</h2><p><a href="https://www.australiancurriculum.edu.au/help/parent-information/what-students-learn-during-the-first-11-years-of-school" target="_blank" rel="noopener">ACARA · Years 7 and 8 learning overview ↗</a><br><a href="https://www.qcaa.qld.edu.au/downloads/aciqv9/mathematics/curriculum/ac9_maths_yr7-10_as_sequence.pdf" target="_blank" rel="noopener">QCAA · Australian Curriculum v9 Years 7–10 Mathematics standards ↗</a></p><p><a href="https://www.australiancurriculum.edu.au/curriculum-information/understand-this-learning-area/science" target="_blank" rel="noopener">Australian Curriculum · Science ↗</a><br><a href="https://www.australiancurriculum.edu.au/support-resources/learning-area-resources/music_examples_of_knowledge_and_skills" target="_blank" rel="noopener">Australian Curriculum · Music knowledge and skills ↗</a><br><a href="https://www.australiancurriculum.edu.au/media/7163/primary_scope_and_sequence_years_5-6.pdf" target="_blank" rel="noopener">Australian Curriculum · Years 5–6 scope and sequence ↗</a></p><div class="modal-actions"><button class="secondary" data-action="sound">Sound effects: ${profile.sound?'on':'off'}</button><button class="secondary" data-action="reset">Reset saved progress</button></div></div>`}
function openModal(html){previousFocus=document.activeElement;$('#modal-content').innerHTML=html;if(!modal.open)modal.showModal()}
function closeModal(){modal.close();previousFocus?.focus?.()}
function topModal(label){return `<div class="modal-top"><span>${label}</span><button class="close" data-action="close" aria-label="Close dialog">×</button></div><div class="modal-audio">${audioButtons()}</div>`}
function zoneChoice(id){const s=SUBJECTS.find(s=>s.id===id);openModal(`${topModal(s.zone)}<h2 class="modal-title" id="modal-title">${s.icon} ${s.name}</h2><p class="sub">${s.desc}. Choose how you want to explore.</p><div class="modal-actions"><button class="primary" data-start="${id}">Play arena →</button><button class="secondary" data-practice="${id}">Untimed practice</button></div><p class="notice" style="margin-top:22px">Arena questions pause the action while you think. Keyboard and touch controls supported.</p>`)}
function practiceChoice(){openModal(`${topModal('PRACTICE MODE')}<h2 class="modal-title" id="modal-title">Pick your brain workout.</h2><p class="sub" style="margin-bottom:20px">10 questions. No timer. Plenty of discoveries.</p><div class="practice-choice"><button class="primary" data-practice="mixed">✦ All-rounder mix</button>${SUBJECTS.map(s=>`<button class="secondary" data-practice="${s.id}">${s.icon} ${s.name}</button>`).join('')}</div>`)}
function shuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function deckFor(subject){return buildQuestionDeck(subject)}
function startPractice(subject,review=false){closeModal();let d=review?shuffle(profile.missed.map(key=>{let [id,index]=key.split(':');return {id,index:+index,q:BANK[id][index]}})):deckFor(subject);quiz={mode:'practice',deck:d.slice(0,review?d.length:10),pos:0,right:0,subject};ask()}
function ask(){resetControls();if(game)game.paused=true;let item;if(quiz.mode==='arena'){if(!quiz.deck.length)quiz.deck=deckFor(quiz.subject);item=quiz.deck.shift()}else item=quiz.deck[quiz.pos];noteQuestionShown(item);quiz.item=item;quiz.answered=false;let s=SUBJECTS.find(s=>s.id===item.id),q=challengeQuestion(item);quiz.item={...item,q};quiz.options=shuffle(q[1].map((label,i)=>({label,i})));openModal(`${topModal(quiz.mode==='preparation'?`${s.name.toUpperCase()} · ${quiz.pos+1} / 10`:`${s.name.toUpperCase()} · ${quiz.pos+1} / ${quiz.deck.length}`)}<h2 class="modal-title" id="modal-title">${q[0]}</h2>${q[5]?'<button class="listen" data-action="listen">♫ Play three notes</button>':''}<div class="answers">${quiz.options.map((o,i)=>`<button class="answer" data-answer="${i}"><b>${String.fromCharCode(65+i)}</b>${o.label}</button>`).join('')}</div><div id="answer-feedback" aria-live="polite"></div><div id="answer-next" class="modal-actions"></div><p class="hint" style="margin:17px 0 0">${quiz.mode==='preparation'?`♥ ${quiz.right} extra hearts earned · 10 questions total · Take your time.`:'Think it through. Mistakes are part of learning.'}</p>`)}
function answer(n){if(!quiz||quiz.answered)return;quiz.answered=true;const item=quiz.item,q=item.q,right=n>=0&&quiz.options[n]?.i===q[2],key=item.id+':'+item.index;profile.answers++;profile.correct+=+right;profile.xp+=right?10:n<0?0:2;profile.coins+=right?5:0;profile.subjects[item.id]??={total:0,correct:0};profile.subjects[item.id].total++;profile.subjects[item.id].correct+=+right;if(right)profile.missed=profile.missed.filter(k=>k!==key);else if(!profile.missed.includes(key))profile.missed.push(key);quiz.right+=+right;
document.querySelectorAll('.answer').forEach((b,i)=>{b.disabled=true;if(quiz.options[i].i===q[2])b.classList.add('correct');else if(i===n)b.classList.add('wrong')});$('#answer-feedback').innerHTML=`<div class="feedback"><strong>${right?'Brilliant! +10 XP · +5 coins':n<0?'Time is up. No heart earned.':'Good effort. +2 XP for learning.'}</strong><br>${q[3]}${q[4]?.url?`<p class="question-source"><a href="${q[4].url}" target="_blank" rel="noopener">${q[4].label} ↗</a><span>Source checked ${q[4].checked}</span></p>`:''}</div>`;$('#answer-next').innerHTML=`<button class="primary" data-action="next">${quiz.pos+1>=quiz.deck.length?(quiz.mode==='preparation'?'See my battle life →':'See my results →'):'Next question →'}</button>`;
if(game&&quiz.mode==='preparation')recordPreparationAnswer(right);GameAudio.effect(right?'correct':'wrong');save();$('#answer-next button').focus()}
function nextQuestion(){if(!quiz?.answered)return;quiz.pos++;if(quiz.pos>=quiz.deck.length){if(quiz.mode==='preparation')preparationResults();else practiceResults()}else ask()}
function practiceResults(){GameAudio.effect('win');let {right,deck}=quiz;openModal(`${topModal('QUEST COMPLETE')}<div class="results"><div class="trophy">✦</div><h2 id="modal-title">Knowledge unlocked!</h2><p>You explored ${deck.length} questions. Every try builds your brain.</p><div class="results-stats"><div><b>${right}/${deck.length}</b><span>CORRECT ANSWERS</span></div><div><b>${right*10+(deck.length-right)*2}</b><span>BASE XP EARNED</span></div></div><div class="modal-actions" style="justify-content:center"><button class="primary" data-action="practice-again">Another quest →</button><button class="secondary" data-action="done">Back to home</button></div></div>`);quiz=null}
function tone(notes,duration=.22){GameAudio.example(notes,duration)}
function startArena(subject){closeModal();cancelAnimationFrame(raf);let hero=ensureAvatar();currentPage='battle';document.body.classList.add('in-battle');window.scrollTo(0,0);$('#crumb').textContent='ARENA';page.innerHTML=`${heading('The Knowledge Grounds',subject==='mixed'?'All-rounder mix · Knowledge across every zone':SUBJECTS.find(s=>s.id===subject).name+' quest · Learn, charge, clash','arena-subtitle')}<section class="battle-shell"><div class="battle-top"><div class="health-hud"><span id="hp"></span><div class="life-track"><i id="life-fill"></i></div></div><div class="wave-hud"><span id="mode-badge">CHALLENGER</span><span id="wave"></span></div><div class="time-hud"><b id="timer">2:00</b><small>TIME LEFT</small></div><button class="secondary" data-action="pause">Ⅱ Pause</button></div><div class="arena-stage"><div class="map-ribbon"><span>✦</span><b id="map-name">KNOWLEDGE GROUNDS</b><small>RANK ${hero.rank}</small></div><div id="boss-hud" hidden><div><strong>THE SCRAMBLER</strong><span id="boss-phase">GUARDIAN</span><b id="boss-number"></b></div><div class="boss-life-track"><i id="boss-life"></i></div></div><canvas id="arena" width="1000" height="650" tabindex="0" aria-label="Arena. Drag the lower-left joystick to move. Hold the lower-right Zap button to attack. Arrow keys or WASD, Space, Q and E also work."></canvas><div class="arena-controls"><div class="movement-hud"><button id="joystick" class="joystick" aria-label="Movement joystick. Drag in any direction to move, release to stop. Keyboard: arrow keys or WASD."><span class="stick-axis stick-up" aria-hidden="true">▲</span><span class="stick-axis stick-right" aria-hidden="true">▶</span><span class="stick-axis stick-down" aria-hidden="true">▼</span><span class="stick-axis stick-left" aria-hidden="true">◀</span><span class="joystick-knob" aria-hidden="true"><span>✥</span></span></button><span class="hud-caption">MOVE</span></div><div class="battle-actions" role="group" aria-label="Attack controls"><button class="dash-button ready" data-action="dash" aria-label="Dodge dash. Keyboard: Shift."><strong>↯ DASH</strong><span id="dash-cooldown">READY</span></button><button class="recharge-button" data-action="recharge" aria-label="Reload energy. Keyboard: Q."><span id="recharge-label">ϟ Reload</span><small>Q</small></button><button class="super-button" data-action="super" aria-label="Super attack. Charge with three correct answers. Keyboard: E."><span class="attack-icon" aria-hidden="true">✦</span><strong>SUPER</strong><span id="charge">0/3</span></button><button class="fire-button" data-action="shoot" aria-label="Zap nearest bot. Hold to keep attacking. Keyboard: Space."><span class="attack-icon" aria-hidden="true">◎</span><strong>ZAP</strong><span class="ammo-label">ϟ <span id="ammo"></span></span></button></div></div></div><div class="battle-bottom"><div class="energy-hud"><b>ENERGY</b><div id="energy-pips"></div></div><p>MOVE · DODGE · OUTSMART</p><span class="keyboard-hint">WASD / arrows · Space · Q · E · Shift</span></div></section>`;
const canvas=$('#arena');canvas.width=canvas.clientWidth<=500?680:1000;canvas.height=Math.round(canvas.width*canvas.clientHeight/canvas.clientWidth);game={w:canvas.width,h:canvas.height,x:canvas.width/2,y:canvas.height/2,hp:hero.hp,maxHp:hero.hp,speed:hero.speed,ammo:hero.ammo,charge:0,enemies:[],bullets:[],particles:[],wave:0,kills:0,time:90,sinceQ:0,paused:true,invincible:2,cooldown:0,ctx:canvas.getContext('2d'),subject,hero};quiz=buildPreparation(subject);game.topicIds=quiz.sections;game.maxHp=game.hero.hp+quiz.deck.length;prepareArena(game);initialiseChallenge(game);initialiseMatch(game);game.prepared=false;game.energyClock=0;spawnWave();last=performance.now();raf=requestAnimationFrame(frame);openModal(`${topModal('READY, HERO?')}<h2 class="modal-title" id="modal-title">${game.mode.name}: charge your life.</h2><p class="feedback">Answer <b>10 random questions total</b>, mixed from your ${fieldIdsFor(game.topicIds).length} selected field${fieldIdsFor(game.topicIds).length===1?'':'s'}. Selecting more fields never adds extra questions. Every correct answer earns 10 preparation points and <b>+1 heart</b> on top of your avatar’s base life.</p><p class="feedback">Then play ${game.totalWaves} uninterrupted waves in ${game.mode.seconds} seconds${game.mode.boss?', including The Scrambler boss':''}. Dash, collect energy and use cover. Questions stay untimed.</p><div class="modal-actions"><button class="primary" data-action="begin">Start ${quiz.deck.length} questions →</button><button class="secondary" data-action="leave">Back to home</button></div>`)}
function burst(x,y,colour,n=14){for(let i=0;i<n;i++){let a=Math.random()*Math.PI*2;game.particles.push({x,y,dx:Math.cos(a)*140,dy:Math.sin(a)*140,life:.6,colour})}}
function frame(t){if(!game)return;const dt=Math.min((t-last)/1000,.045);last=t;if(!game.paused&&!updateArena(dt))return;if(game)renderArena(game);raf=requestAnimationFrame(frame)}
function finishArena(win){showMatchResults(win)}
function pause(){if(!game)return;game.paused=true;resetControls();openModal(`${topModal('ARENA PAUSED')}<h2 id="modal-title">Take a breather.</h2><p class="feedback">Your arena timer is paused. Ready when you are.</p><div class="modal-actions"><button class="primary" data-action="resume">Resume →</button><button class="secondary" data-rematch="${game.subject}">Restart match</button><button class="secondary" data-action="leave">Leave match</button></div>`)}
function closeRequest(){if(quiz?.mode==='preparation'){cancelPreparation();return}if(quiz&&$('#answer-feedback')){if(quiz.mode==='arena'){if(quiz.answered)nextQuestion();else{closeModal();game.paused=false;game.sinceQ=0;game.invincible=1.5;keys={}}}else{openModal(`${topModal('LEAVE PRACTICE?')}<h2 id="modal-title">Your answers are already saved.</h2><p class="feedback">Return home or keep going with this question.</p><div class="modal-actions"><button class="primary" data-action="continue-practice">Keep learning</button><button class="secondary" data-action="done">Back to home</button></div>`)}}else if(game){closeModal();game.paused=false;keys={}}else{closeModal();if(currentPage==='battle')navigate('home')}}
document.addEventListener('click',e=>{let b=e.target.closest('button,a.brand');if(!b)return;if(b.matches('a.brand')){e.preventDefault();navigate('home')}if(b.dataset.topic){const id=b.dataset.topic;topicDraft=topicDraft.includes(id)?topicDraft.filter(x=>x!==id):[...topicDraft,id];drawTopicPicker();document.querySelector('[data-topic="'+id+'"]')?.focus({preventScroll:true})}if(b.dataset.topicChoice){topicDraft=b.dataset.topicChoice==='all'?SUBJECTS.map(s=>s.id):[];drawTopicPicker()}if(b.dataset.difficulty){profile.difficulty=b.dataset.difficulty;save();page.innerHTML=home();document.querySelector('[data-difficulty="'+profile.difficulty+'"]')?.focus({preventScroll:true})}if(b.dataset.page)navigate(b.dataset.page);if(b.dataset.subject)zoneChoice(b.dataset.subject);if(b.dataset.breedPreview)previewBreed(b.dataset.breedPreview);if(b.dataset.petTab){petTab=b.dataset.petTab;page.innerHTML=heroes()}if(b.dataset.hero&&selectAvatar(b.dataset.hero)){navigate('heroes')}if(b.dataset.start)startArena(b.dataset.start);if(b.dataset.rematch)startArena(b.dataset.rematch);if(b.dataset.practice)startPractice(b.dataset.practice);if(b.dataset.answer!==undefined)answer(+b.dataset.answer);switch(b.dataset.action){case'mixed':chooseBattleTopics();break;case'start-warmup':if(topicDraft.length){profile.battleTopics=[...topicDraft];save();startArena('mixed')}break;case'enter-battle':enterPreparedBattle();break;case'continue-warmup':if(quiz.answered)nextQuestion();else ask();break;case'practice':case'practice-again':practiceChoice();break;case'review':if(profile.missed.length)startPractice('mixed',true);break;case'next':nextQuestion();break;case'close':closeRequest();break;case'done':closeModal();quiz=null;navigate('home');break;case'begin':ask();break;case'shoot':shoot();break;case'recharge':reloadEnergy();break;case'super':superAttack();break;case'dash':dash();break;case'pause':pause();break;case'resume':closeModal();game.paused=false;resetControls();break;case'leave':closeModal();quiz=null;navigate('home');break;case'continue-practice':if(quiz.answered){if(++quiz.pos>=quiz.deck.length){practiceResults();break}}ask();break;case'listen':if(profile.sound)tone([330,440,554],.35);else toast('Sound is muted. Turn on Sound in the Audio controls to listen.');break;case'sound':profile.sound=!profile.sound;save();refreshAudioUI();navigate('parents');break;case'reset':openModal(`${topModal('RESET PROGRESS')}<h2 id="modal-title">Start a new adventure?</h2><p class="feedback">This clears all XP, coins and saved answers from this browser. This cannot be undone.</p><div class="modal-actions"><button class="secondary" data-action="close">Keep progress</button><button class="primary" data-action="confirm-reset">Clear saved progress</button></div>`);break;case'confirm-reset':profile=fresh();save();closeModal();navigate('home');break}});
document.addEventListener('keydown',e=>{if(!game||game.paused||modal.open)return;let k=e.key.length===1?e.key.toLowerCase():e.key;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' ','w','a','s','d','e','q'].includes(k)){e.preventDefault();keys[k]=true;if(!e.repeat&&k==='q')reloadEnergy();if(!e.repeat&&k==='e')superAttack()}if(k==='Shift'&&!e.repeat){e.preventDefault();dash()}if(k==='Escape')pause()});document.addEventListener('keyup',e=>{keys[e.key.length===1?e.key.toLowerCase():e.key]=false});window.addEventListener('blur',()=>{resetControls();if(game&&!game.paused)pause()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&game&&!game.paused)pause()});
function renderStick(){const el=$('#joystick');if(!el)return;const radius=el.getBoundingClientRect().width*.32;el.style.setProperty('--stick-x', (stick.x*radius)+'px');el.style.setProperty('--stick-y',(stick.y*radius)+'px');el.classList.toggle('engaged',stick.pointerId!==null)}
function resetControls(){keys={};stick.pointerId=null;stick.x=stick.y=0;firePointerId=null;renderStick();document.querySelector('.fire-button')?.classList.remove('firing')}
function moveStick(e){if(e.pointerId!==stick.pointerId)return;const box=$('#joystick').getBoundingClientRect(),radius=box.width*.32;let x=(e.clientX-box.left-box.width/2)/radius,y=(e.clientY-box.top-box.height/2)/radius;const distance=Math.hypot(x,y);if(distance<.12){x=y=0}else if(distance>1){x/=distance;y/=distance}stick.x=x;stick.y=y;renderStick()}
function pointerDown(e){const joystick=e.target.closest('#joystick'),fire=e.target.closest('.fire-button');if(!game||game.paused||modal.open)return;if(joystick&&stick.pointerId===null){e.preventDefault();stick.pointerId=e.pointerId;joystick.setPointerCapture(e.pointerId);moveStick(e)}else if(fire&&firePointerId===null){e.preventDefault();firePointerId=e.pointerId;fire.setPointerCapture(e.pointerId);fire.classList.add('firing');shoot()}}
function pointerEnd(e){if(e.pointerId===stick.pointerId){stick.pointerId=null;stick.x=stick.y=0;renderStick()}if(e.pointerId===firePointerId){firePointerId=null;document.querySelector('.fire-button')?.classList.remove('firing')}}
document.addEventListener('pointerdown',pointerDown);document.addEventListener('pointermove',e=>{if(e.pointerId===stick.pointerId){e.preventDefault();moveStick(e)}},{passive:false});document.addEventListener('pointerup',pointerEnd);document.addEventListener('pointercancel',pointerEnd);document.addEventListener('lostpointercapture',pointerEnd);
modal.addEventListener('cancel',e=>{e.preventDefault();closeRequest()});initBreedArt();initAudio();updateBar();navigate('home');



